// Evento fictício para validar o HUB sem depender de CRM.
// Antes do teste no banco, cadastre CLIENTE_TESTE em meta_hub_clientes.
return [{
  json: {
    modo_teste: true,
    cliente: 'CLIENTE_TESTE',
    evento_externo_id: 'TESTE-QUALIFICADO-001',
    lead_externo_id: 'LEAD-TESTE-001',
    sistema_origem: 'teste_n8n',
    sessao_id: 'SESSAO-TESTE-001',
    evento: 'lead_qualificado',
    ocorrido_em: '2026-08-14T10:30:00-03:00',
    score_qualificacao: 82,
    moeda: 'BRL',
    pode_compartilhar_meta: true,
    pode_usar_publico: true,
    action_source: 'other',
    identificadores: {
      email: 'lead.teste@example.com',
      telefone: '5551999999999',
      external_id: 'LEAD-TESTE-001'
    },
    atribuicao: {
      conta_anuncio: 'CONTA_TESTE',
      id_campanha: 'CAMPANHA_TESTE',
      id_conjunto: 'CONJUNTO_TESTE',
      id_anuncio: 'ANUNCIO_TESTE',
      origem_atribuicao: 'teste_controlado',
      confianca_atribuicao: 'alta'
    },
    metadata: {
      ambiente: 'teste'
    }
  }
}];

// Converte Webhook ou teste manual para o contrato canônico do HUB.
const origem = $json.body && typeof $json.body === 'object' ? $json.body : $json;

const eventosPermitidos = new Set([
  'conversa_iniciada',
  'lead_identificado',
  'lead_qualificado',
  'agendamento',
  'proposta',
  'venda',
  'desqualificado'
]);

function texto(valor) {
  if (valor === undefined || valor === null) return '';
  return String(valor).trim();
}

function numeroOuNull(valor) {
  if (valor === undefined || valor === null || valor === '') return null;
  const numero = Number(String(valor).replace(',', '.'));
  return Number.isFinite(numero) ? numero : null;
}

function booleano(valor, padrao = false) {
  if (typeof valor === 'boolean') return valor;
  if (valor === 1 || valor === '1' || String(valor).toLowerCase() === 'true') return true;
  if (valor === 0 || valor === '0' || String(valor).toLowerCase() === 'false') return false;
  return padrao;
}

const cliente = texto(origem.cliente);
const eventoExternoId = texto(origem.evento_externo_id);
const leadExternoId = texto(origem.lead_externo_id);
const sistemaOrigem = texto(origem.sistema_origem) || 'desconhecido';
const evento = texto(origem.evento).toLowerCase();
const ocorridoEm = texto(origem.ocorrido_em);

const faltando = [];
if (!cliente) faltando.push('cliente');
if (!eventoExternoId) faltando.push('evento_externo_id');
if (!leadExternoId) faltando.push('lead_externo_id');
if (!evento) faltando.push('evento');
if (!ocorridoEm) faltando.push('ocorrido_em');

if (faltando.length) {
  throw new Error(`Campos obrigatórios ausentes: ${faltando.join(', ')}`);
}

if (!eventosPermitidos.has(evento)) {
  throw new Error(`Evento não permitido: ${evento}`);
}

if (Number.isNaN(Date.parse(ocorridoEm))) {
  throw new Error('ocorrido_em deve ser uma data ISO 8601 válida');
}

const identificadores = origem.identificadores || {};
const atribuicao = origem.atribuicao || {};

return [{
  json: {
    modo_teste: booleano(origem.modo_teste, false),
    cliente,
    evento_externo_id: eventoExternoId,
    lead_externo_id: leadExternoId,
    sistema_origem: sistemaOrigem,
    sessao_id: texto(origem.sessao_id) || null,
    evento,
    ocorrido_em: ocorridoEm,
    score_qualificacao: numeroOuNull(origem.score_qualificacao),
    valor: numeroOuNull(origem.valor),
    moeda: (texto(origem.moeda) || 'BRL').toUpperCase(),
    pode_compartilhar_meta: booleano(origem.pode_compartilhar_meta, false),
    pode_usar_publico: booleano(origem.pode_usar_publico, false),
    action_source: texto(origem.action_source) || null,
    identificadores: {
      email: texto(identificadores.email).toLowerCase() || null,
      telefone: texto(identificadores.telefone) || null,
      external_id: texto(identificadores.external_id) || leadExternoId
    },
    atribuicao: {
      conta_anuncio: texto(atribuicao.conta_anuncio) || null,
      id_campanha: texto(atribuicao.id_campanha) || null,
      id_conjunto: texto(atribuicao.id_conjunto) || null,
      id_anuncio: texto(atribuicao.id_anuncio) || null,
      meta_lead_id: texto(atribuicao.meta_lead_id) || null,
      fbc: texto(atribuicao.fbc) || null,
      fbp: texto(atribuicao.fbp) || null,
      ctwa_clid: texto(atribuicao.ctwa_clid) || null,
      origem_atribuicao: texto(atribuicao.origem_atribuicao) || 'desconhecida',
      confianca_atribuicao: texto(atribuicao.confianca_atribuicao) || 'desconhecida'
    },
    metadata: origem.metadata && typeof origem.metadata === 'object' ? origem.metadata : {}
  }
}];

// Padroniza a resposta da função SQL para integrações externas.
const resultado = $json.resultado || $json;

return [{
  json: {
    status: resultado.ok ? 'RECEBIDO' : 'ERRO',
    ...resultado
  }
}];
